gq 3;

query colleagues($of: String) {
  match {
    $p: Person { handle: $of }
    $p worksAt $c
    $q worksAt $c
    $q.handle != $p.handle
  }
  return { $q }
}

query colleagues_of_colleagues($of: String) {
  match {
    from { match { from colleagues($of) } return { $q as m } }
    from { match { from colleagues($m.handle) } return { $q as r } }
  }
  return distinct { $r.name }
}
